/**
 * The 3D room: renderer, rooms built by the scene builder, clicks, zones, portals between rooms,
 * media, hidden objects, graph effects, and immersive VR, AR and mixed reality.
 *
 * The click-to-raycast-to-hotspot-panel flow follows mod_gear's viewer.
 *
 * A 360° photo room (environment type panorama) is seen from its centre: no walking and no
 * teleport, drag or touch to look (or move the phone), keys turn and tilt, the wheel or a pinch
 * zooms (field of view 30° to 90°, reset in each room), up to ±85° up and down. The photo sphere
 * follows the head in VR, snap turn stays, AR and mixed reality are not offered there, and the
 * others of a live room stand on a ring around the centre.
 *
 * @module     vrroomruntime_builtin/viewer
 * @copyright  2026 Boban Blagojevic
 * @copyright  2026 Adam Jenkins <adam@wisecat.net>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import * as THREE from 'vrroomruntime_builtin/three';
import {GLTFLoader} from 'vrroomruntime_builtin/three';
import {register as registerMozLightmap} from 'vrroomruntime_builtin/mozlightmap';
import Log from 'core/log';
import Pending from 'core/pending';
import {getString, getStrings} from 'core/str';
import {buildScene, DEG} from 'vrroomruntime_builtin/scenebuilder';
import {attach} from 'vrroomruntime_builtin/controls';
import {createPanels} from 'vrroomruntime_builtin/panels';
import {detect, createXr, createWristPanel} from 'vrroomruntime_builtin/xr';
import {createXrInput} from 'vrroomruntime_builtin/xrinput';
import {createXrPanels} from 'vrroomruntime_builtin/xrpanel';
import {createAvatarLayer} from 'vrroomruntime_builtin/live/avatars';
import {createStagebar} from 'vrroomruntime_builtin/stagebar';
import {layoutKey, spreadOffset} from 'vrroomruntime_builtin/spawn';
import {region, plainText, announce, showMessage, clearMessage, startScene} from 'vrroomruntime_builtin/util';

/** Distance within which Enter activates the object in the middle of the screen (m). */
const REACH = 6;

/** Eye height of the desktop camera (m). */
const EYE = 1.6;

/** How long the "locked" message stays (ms). */
const MESSAGE_TIME = 4000;

/** How often the wrist panel is refreshed (s). */
const WRIST_INTERVAL = 0.5;

/** Vertical field of view on a landscape screen (degrees). */
const FOV = 70;

/** Narrowest horizontal field of view: a portrait phone widens its view to keep this (degrees). */
const MIN_HFOV = 72;

/** Widest vertical field of view a portrait screen gets (degrees). */
const MAX_FOV = 110;

/** Zoom range of a 360° photo room: narrowest and widest vertical field of view (degrees). */
const PANORAMA_FOV = [30, 90];

/** How far up and down the view tilts in a 360° photo room, and elsewhere (degrees). */
const PANORAMA_PITCH = 85;
const ROOM_PITCH = 80;

/** How far a click or a controller ray selects in a 360° photo room (m): past the furthest item. */
const PANORAMA_REACH = 45;

/** How far a controller ray selects elsewhere (m), as xrinput's default. */
const XR_REACH = 30;

/**
 * Where each session's walker last stood in the 3D room, so switching to the list view and back
 * keeps the place (in a live room the start point may be taken by someone else meanwhile).
 *
 * @type {WeakMap<Object, Object>} session → {scene, position, yaw, key}
 */
const lastplaces = new WeakMap();

/**
 * Whether the browser can create a WebGL context.
 *
 * @returns {boolean}
 */
export const isWebGLAvailable = () => {
    try {
        if (!window.WebGLRenderingContext) {
            return false;
        }
        const canvas = document.createElement('canvas');
        const gl = canvas.getContext('webgl2') || canvas.getContext('webgl');
        if (!gl) {
            return false;
        }
        const lose = gl.getExtension('WEBGL_lose_context');
        if (lose) {
            lose.loseContext();
        }
        return true;
    } catch (e) {
        return false;
    }
};

/**
 * Read a 3-vector or return a default.
 *
 * @param {*} value Value.
 * @param {number[]} fallback Default.
 * @returns {number[]}
 */
const vec3 = (value, fallback) => {
    if (!Array.isArray(value) || value.length !== 3) {
        return fallback.slice();
    }
    return value.map((v, i) => (Number.isFinite(Number(v)) ? Number(v) : fallback[i]));
};

/**
 * Seconds as m:ss.
 *
 * @param {number} seconds Whole seconds.
 * @returns {string}
 */
const clockText = (seconds) => {
    const s = Math.max(0, Math.floor(seconds));
    const minutes = Math.floor(s / 60);
    const rest = s % 60;
    return `${minutes}:${rest < 10 ? '0' : ''}${rest}`;
};

/**
 * Set up the renderer and the first room once the strings are loaded, then run the room.
 *
 * @param {Object} base {root, session, config, live, stage, canvas, scenes} from start().
 * @param {string[]} values The strings start() loaded, in its order.
 * @returns {Promise<Object>} {stop()}
 */
const prepareRoom = (base, values) => {
    const {root, session, config, live, stage, canvas, scenes} = base;
    const [loading, modelfailed, locked, entervr, enterar, entermr, exitxr, xrinsecure, xrfailed, xrplace,
        panoramafailed] = values;
    const strings = {loading, modelfailed, locked, entervr, enterar, entermr, exitxr, xrinsecure, xrfailed, xrplace,
        panoramafailed};
    if (!startScene(config)) {
        throw new Error('No scene in the launch config');
    }
    stage.classList.remove('d-none');
    showMessage(root, loading, 'info');

    const renderer = new THREE.WebGLRenderer({canvas: canvas, antialias: true});
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.xr.enabled = true;
    const scene3 = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(FOV, 16 / 9, 0.05, 300);
    const rig = new THREE.Group();
    rig.name = 'vrroom-rig';
    rig.add(camera);
    scene3.add(rig);
    // Hubs rooms keep their baked lighting (MOZ_lightmap).
    const loader = registerMozLightmap(new GLTFLoader());
    const textureloader = new THREE.TextureLoader();
    let stopped = false;

    const roomOptions = () => ({
        loader: loader,
        textureloader: textureloader,
        // A GPU that cannot hold an 8192 px texture gets the phone copy of a 360° photo.
        maxTextureSize: renderer.capabilities ? renderer.capabilities.maxTextureSize : undefined,
        hidden: session.getState().hidden,
        onLoadError: (error, item) => {
            Log.debug(error);
            if (!stopped) {
                const photo = item && item.kind === 'environment' && item.type === 'panorama';
                showMessage(root, photo ? strings.panoramafailed : strings.modelfailed, 'warning');
            }
        },
        roomName: (sceneid) => {
            const target = scenes.find((s) => s.id === sceneid);
            return target ? target.name : null;
        },
    });

    let doc = null;
    let resumestate = null;
    // The place left when the 3D room last closed in this page, else the saved resume position.
    const remembered = lastplaces.get(session) || null;
    const resumeload = remembered ? Promise.resolve(remembered) : session.loadResume();
    return resumeload.then((resume) => {
        const resumed = resume ? scenes.find((s) => s.id === resume.scene) : null;
        // A position saved before the room's surroundings or start point changed is not used again.
        const usable = resumed && resume.key === layoutKey(resumed);
        doc = usable ? resumed : startScene(config);
        resumestate = usable ? resume : null;
        return buildScene(THREE, doc, roomOptions());
    }).then((handle) => run({
        root, session, config, scenes, stage, canvas, renderer, scene3, camera, rig, strings, roomOptions,
        doc, handle, resume: resumestate, live: live, setStopped: () => {
            stopped = true;
        },
    })).catch((error) => {
        stopped = true;
        renderer.setAnimationLoop(null);
        renderer.dispose();
        clearMessage(root, loading);
        throw error;
    });
};

/**
 * Start the 3D view.
 *
 * @param {HTMLElement} root The VR room root element (holding the shell).
 * @param {Object} session The session.
 * @param {Object} config Launch config.
 * @param {Object} [options] {live: LiveController|null} — the live room, when there is one.
 * @returns {Promise<Object>} {stop()}
 */
export const start = (root, session, config, options = {}) => {
    const live = options && options.live ? options.live : null;
    const pending = new Pending('vrroomruntime_builtin/viewer:start');
    const stage = region(root, 'vrroom-stage');
    const canvas = region(root, 'vrroom-canvas');
    const scenes = Array.isArray(config.scenes) ? config.scenes : [];

    return getStrings([
        {key: 'loading', component: 'vrroomruntime_builtin'},
        {key: 'modelloadfailed', component: 'vrroomruntime_builtin'},
        {key: 'stationlocked', component: 'vrroomruntime_builtin'},
        {key: 'entervr', component: 'vrroomruntime_builtin'},
        {key: 'enterar', component: 'vrroomruntime_builtin'},
        {key: 'entermr', component: 'vrroomruntime_builtin'},
        {key: 'exitxr', component: 'vrroomruntime_builtin'},
        {key: 'xrinsecure', component: 'vrroomruntime_builtin'},
        {key: 'xrfailed', component: 'vrroomruntime_builtin'},
        {key: 'xrplace', component: 'vrroomruntime_builtin'},
        {key: 'panoramaloadfailed', component: 'vrroomruntime_builtin'},
    ]).then((values) => prepareRoom({root, session, config, live, stage, canvas, scenes}, values)).then((handle) => {
        pending.resolve();
        return handle;
    }, (error) => {
        stage.classList.add('d-none');
        pending.resolve();
        throw error;
    });
};

/**
 * Run the room: picking, zones, rooms, effects, XR and the frame loop.
 *
 * @param {Object} p Everything prepared by start().
 * @returns {Object} {stop()}
 */
const run = (p) => {
    const {root, session, scenes, stage, canvas, renderer, scene3, camera, rig, strings, roomOptions, resume} = p;
    let current = {doc: p.doc, handle: p.handle};
    // Bumped whenever the set of obstacles may have changed (see obstacleMeshes()).
    let obstacleversion = 0;
    const refreshObstaclesWhenLoaded = (handle) => {
        Promise.resolve(handle.ready).then(() => {
            obstacleversion++;
            // Declared further down; this runs after the room has started.
            recheckSpawn(handle);
            return undefined;
        }).catch(() => {
            obstacleversion++;
        });
    };
    let stopped = false;
    let switching = null;
    const inside = new Set();
    const enteredrecorded = new Set();
    const grabbed = new Set();
    let messagetimer = null;

    // XR state.
    let xrmode = null;
    let placed = false;
    let placement = null;
    let lasthit = null;
    let xrinput = null;
    let xrpanels = null;
    let xrpanelspromise = null;
    let wrist = null;
    let wristclock = 0;
    let xr = null;
    const reticle = new THREE.Mesh(
        new THREE.RingGeometry(0.07, 0.09, 32).rotateX(-Math.PI / 2),
        new THREE.MeshBasicMaterial({color: 0xffffff, transparent: true, opacity: 0.9})
    );
    reticle.matrixAutoUpdate = false;
    reticle.visible = false;
    reticle.name = 'vrroom-xr-place';
    scene3.add(reticle);

    const xrstatus = region(root, 'vrroom-xr-status');
    const exitbutton = stage.querySelector('[data-action="vrroom-exit-xr"]');
    const sceneid = () => current.doc.id;
    const findItem = (id) => (Array.isArray(current.doc.interactables) ? current.doc.interactables : [])
        .find((i) => i.id === id) || null;
    const spawnsOf = (doc) => (Array.isArray(doc.spawn) ? doc.spawn : []);
    const zonesOf = (doc) => (Array.isArray(doc.zones) ? doc.zones : []);
    // Whether the current room is a 360° photo, seen from its centre.
    const isPanorama = () => !!(current.doc.environment && current.doc.environment.type === 'panorama');
    const panoramaSphere = () => (current.handle.environment ? current.handle.environment.panorama || null : null);
    // The zoomed field of view of a photo room (null: not zoomed).
    let zoomfov = null;

    scene3.add(current.handle.root);

    // The other people in a live room, as avatars in the current room.
    const avatars = p.live ? createAvatarLayer(THREE, {
        live: p.live,
        camera: camera,
        getRoomRoot: () => current.handle.root,
        getSceneId: () => current.doc.id,
        getGrip: (h) => (xrinput ? xrinput.getGrip(h) : null),
        getHand: (i) => renderer.xr.getHand(i),
        isPanorama: () => isPanorama(),
    }) : null;
    if (avatars) {
        avatars.setRoom(current.handle.root, current.doc.id);
        avatars.setMode('3d');
    }
    // Webcams: the avatar layer registers itself with the live controller (avatars.js), which hands
    // each person's video to their avatar's face screen.

    const panels = createPanels(stage, session, {
        onClose: () => canvas.focus({preventScroll: true}),
    });

    // In-world panels are used in VR, mixed reality, and AR without a DOM overlay.
    const worldPanels = () => !!xrmode && !(xrmode === 'ar' && xr && xr.domOverlay);

    const ensureXrPanels = () => {
        if (!xrpanelspromise) {
            xrpanelspromise = createXrPanels(THREE, {parent: scene3, camera: camera, session: session})
                .then((created) => {
                    if (stopped) {
                        created.dispose();
                        return null;
                    }
                    xrpanels = created;
                    return created;
                })
                .catch((error) => {
                    Log.debug(error);
                    xrpanelspromise = null;
                    return null;
                });
        }
        return xrpanelspromise;
    };

    // A short message: in the page, in the AR overlay, or on an in-world panel (sticky ones stay).
    const notify = (text, level = 'warning', sticky = false) => {
        announce(root, text);
        if (xrmode && worldPanels()) {
            if (xrpanels) {
                xrpanels.showMessage(text);
            }
            return;
        }
        if (xrmode && xrstatus) {
            xrstatus.textContent = text;
            xrstatus.classList.remove('d-none');
        } else {
            showMessage(root, text, level);
        }
        if (messagetimer) {
            window.clearTimeout(messagetimer);
            messagetimer = null;
        }
        if (sticky) {
            return;
        }
        messagetimer = window.setTimeout(() => {
            messagetimer = null;
            clearMessage(root, text);
            if (xrstatus && xrstatus.textContent === text) {
                xrstatus.textContent = '';
                xrstatus.classList.add('d-none');
            }
        }, MESSAGE_TIME);
    };

    const showLocked = () => notify(strings.locked, 'warning');

    const openHotspot = (hotspot) => {
        if (worldPanels()) {
            if (xrpanels) {
                xrpanels.openInteractable(hotspot);
            }
        } else {
            panels.openInteractable(hotspot);
        }
    };

    const openQuestion = (slot) => {
        if (worldPanels()) {
            if (xrpanels) {
                xrpanels.openQuestion(Number(slot));
            }
        } else {
            panels.openQuestion(Number(slot));
        }
    };

    // Media.
    const mediaOf = (id) => {
        const record = current.handle.items.get(id);
        return record && record.media ? record : null;
    };
    const playMedia = (record) => {
        const element = record.media;
        if (element.ended) {
            element.currentTime = 0;
        }
        Promise.resolve(element.play()).then(() => getString('mediaplay', 'vrroomruntime_builtin',
            plainText(record.item.name || ''))).then((text) => announce(root, text)).catch((error) => Log.debug(error));
    };
    const toggleMedia = (id) => {
        const record = mediaOf(id);
        if (!record) {
            return;
        }
        if (record.media.paused) {
            playMedia(record);
        } else {
            record.media.pause();
            getString('mediapause', 'vrroomruntime_builtin', plainText(record.item.name || ''))
                .then((text) => announce(root, text))
                .catch((error) => Log.debug(error));
        }
    };

    // Picking with the mouse or a tap.
    const raycaster = new THREE.Raycaster();
    const isShown = (object) => {
        let o = object;
        while (o) {
            if (o.visible === false) {
                return false;
            }
            o = o.parent;
        }
        return true;
    };
    const pick = (ndc, far) => {
        camera.updateMatrixWorld(true);
        raycaster.setFromCamera(new THREE.Vector2(ndc.x, ndc.y), camera);
        raycaster.far = far;
        const hits = raycaster.intersectObjects(current.handle.pickTargets(), true);
        for (const hit of hits) {
            if (!isShown(hit.object) || hit.object.isLine || hit.object.isLineSegments) {
                continue;
            }
            const found = current.handle.findPickable(hit.object);
            if (found && found.kind === 'interactable') {
                return findItem(found.id);
            }
            if (hit.object.isSprite) {
                continue;
            }
            // The first solid thing that is not an interactable blocks the click.
            return null;
        }
        return null;
    };

    // Zones the player is in, and leaving them all (room change, XR mode change).
    const leaveZones = () => {
        inside.forEach((zoneid) => {
            if (enteredrecorded.has(zoneid)) {
                session.record('exited', 'zone', zoneid, sceneid());
            }
        });
        inside.clear();
        enteredrecorded.clear();
    };

    const enterZone = (zone) => {
        if (session.isZoneLocked(zone.id)) {
            showLocked();
            return;
        }
        enteredrecorded.add(zone.id);
        session.record('entered', 'zone', zone.id, sceneid());
    };

    // Placement of the room in AR (table top) and mixed reality (room scale).
    const userYaw = () => {
        const dir = camera.getWorldDirection(new THREE.Vector3());
        return Math.atan2(-dir.x, -dir.z);
    };
    const firstSpawn = (doc, spawnid) => {
        const list = spawnsOf(doc);
        return list.find((s) => s.id === spawnid) || list[0] || {position: [0, 0, 0], yaw: 0};
    };
    const applyPlacement = () => {
        const roomroot = current.handle.root;
        if (!placement) {
            roomroot.position.set(0, 0, 0);
            roomroot.rotation.set(0, 0, 0);
            roomroot.scale.set(1, 1, 1);
            return;
        }
        roomroot.scale.setScalar(placement.scale);
        roomroot.rotation.set(0, placement.rotation, 0);
        const offset = new THREE.Vector3(placement.centre[0], 0, placement.centre[2])
            .multiplyScalar(placement.scale)
            .applyAxisAngle(new THREE.Vector3(0, 1, 0), placement.rotation);
        roomroot.position.copy(placement.point).sub(offset);
        roomroot.updateMatrixWorld(true);
    };
    const arScale = (doc) => {
        const xr = doc.xr && typeof doc.xr === 'object' ? doc.xr : {};
        const value = Number(xr.arscale);
        if (xr.arscale !== null && xr.arscale !== undefined && Number.isFinite(value) && value > 0) {
            return value;
        }
        const b = current.handle.environment.bounds;
        const extent = b ? Math.max(b.max[0] - b.min[0], b.max[2] - b.min[2]) : 10;
        return 1 / Math.max(extent, 0.01);
    };
    // Compute the placement of the current room at a floor or table point.
    const placeAt = (point, spawnid) => {
        const spawn = firstSpawn(current.doc, spawnid);
        const spawnyaw = (Number(spawn.yaw) || 0) * DEG;
        if (xrmode === 'ar') {
            const b = current.handle.environment.bounds;
            const centre = b ? [(b.min[0] + b.max[0]) / 2, 0, (b.min[2] + b.max[2]) / 2] : [0, 0, 0];
            placement = {point: point.clone(), rotation: userYaw() - spawnyaw, scale: arScale(current.doc), centre: centre};
        } else {
            placement = {point: point.clone(), rotation: userYaw() - spawnyaw, scale: 1, centre: vec3(spawn.position, [0, 0, 0])};
        }
        applyPlacement();
    };
    // The floor point under the head in mixed reality.
    const feetPoint = () => {
        const head = camera.getWorldPosition(new THREE.Vector3());
        head.y = placement ? placement.point.y : head.y - EYE;
        return head;
    };

    const placeRoom = () => {
        let point = null;
        if (lasthit) {
            const m = new THREE.Matrix4().fromArray(lasthit.transform.matrix);
            point = new THREE.Vector3().setFromMatrixPosition(m);
        } else if (xrmode === 'mr') {
            point = feetPoint();
        }
        if (!point) {
            notify(strings.xrplace, 'info', true);
            return;
        }
        placeAt(point, null);
        placed = true;
        reticle.visible = false;
        if (xrstatus) {
            xrstatus.textContent = '';
            xrstatus.classList.add('d-none');
        }
        if (xrpanels) {
            xrpanels.close();
        }
    };

    // A free spot at a start point of the current room, facing into the room. In a live room with
    // other people in it, each person gets their own place on a ring around the start point (the same
    // one every time), in sight of it and away from the others; someone alone starts at the start point.
    const safeSpawn = (spawnid) => {
        const spawn = firstSpawn(current.doc, spawnid);
        const base = vec3(spawn.position, [0, 0, 0]);
        const yaw = Number(spawn.yaw) || 0;
        if (isPanorama()) {
            // Everyone looks from the centre of the photo; the others are drawn on a ring around it.
            return {position: [0, 0, 0], yaw: yaw, free: true};
        }
        current.handle.root.updateMatrixWorld(true);
        const avoid = avatars ? avatars.getPeerPositions() : [];
        const others = avoid.length > 0 || (p.live && p.live.isJoined() && p.live.getPeers().length > 0);
        if (p.live && others) {
            const offset = spreadOffset(String((p.config && p.config.userid) || ''));
            const spread = controls.findStart([base[0] + offset[0], 0, base[2] + offset[1]], yaw, {
                avoid: avoid,
                from: [base[0], base[2]],
                maxradius: 1,
            });
            if (spread.free) {
                return spread;
            }
        }
        return controls.findStart(base, yaw, {avoid: avoid});
    };

    // A walker put at a start point while nobody else was in the live room yet: once others are there
    // (they joined, or this person pressed Join after entering), they get their own place on the ring
    // around the start point, unless they have already moved.
    let atstart = null;
    let spreadclock = 0;
    const markAtStart = (spawnid) => {
        const position = controls.getPosition();
        atstart = p.live && !isPanorama() ? {x: position[0], z: position[2], spawnid: spawnid} : null;
    };
    const spreadIfJoined = (dt) => {
        spreadclock += dt;
        if (!atstart || spreadclock < 0.5) {
            return;
        }
        spreadclock = 0;
        const position = controls.getPosition();
        if (xrmode || Math.abs(position[0] - atstart.x) > 1e-3 || Math.abs(position[2] - atstart.z) > 1e-3) {
            atstart = null;
            return;
        }
        if (!p.live.isJoined() || !p.live.getPeers().length) {
            return;
        }
        const spawnid = atstart.spawnid;
        atstart = null;
        current.handle.root.updateMatrixWorld(true);
        const spot = safeSpawn(spawnid);
        controls.teleport(spot.position, spot.yaw);
    };

    // Where the walker was put, until they move: models still loading can block the spot, and it is
    // checked again once they are in.
    let placedat = null;
    const rememberSpawn = (spawnid, saved) => {
        const position = controls.getPosition();
        placedat = {handle: current.handle, x: position[0], z: position[2], spawnid: spawnid, saved: saved};
    };
    const recheckSpawn = (handle) => {
        if (stopped || xrmode || !placedat || placedat.handle !== handle || handle !== current.handle || isPanorama()) {
            return;
        }
        const position = controls.getPosition();
        if (Math.abs(position[0] - placedat.x) > 1e-3 || Math.abs(position[2] - placedat.z) > 1e-3) {
            placedat = null;
            return;
        }
        const saved = placedat.saved;
        const spawnid = placedat.spawnid;
        placedat = null;
        handle.root.updateMatrixWorld(true);
        if (controls.canStand(position)) {
            return;
        }
        const spot = safeSpawn(saved ? null : spawnid);
        controls.teleport(spot.position, spot.yaw);
    };

    // Put the player (or, in mixed reality, the room) at a start point of the current room.
    const placeAtSpawn = (spawnid) => {
        if (xrmode === 'vr' && xrinput) {
            const spot = safeSpawn(spawnid);
            xrinput.moveHeadTo(spot.position, spot.yaw);
        } else if (xrmode === 'mr') {
            if (placed) {
                placeAt(feetPoint(), spawnid);
            }
        } else if (xrmode === 'ar') {
            if (placement) {
                const b = current.handle.environment.bounds;
                placement.scale = arScale(current.doc);
                placement.centre = b ? [(b.min[0] + b.max[0]) / 2, 0, (b.min[2] + b.max[2]) / 2] : [0, 0, 0];
                applyPlacement();
            }
        } else {
            const spot = safeSpawn(spawnid);
            controls.teleport(spot.position, spot.yaw);
            rememberSpawn(spawnid, null);
            markAtStart(spawnid);
        }
    };

    // How the room looks in the current mode.
    const applyLook = () => {
        const env = current.handle.environment;
        scene3.background = xrmode === 'ar' || xrmode === 'mr' ? null : env.background;
        env.shell.forEach((mesh) => {
            mesh.visible = xrmode !== 'mr';
        });
        if (env.panorama) {
            env.panorama.visible = xrmode !== 'ar' && xrmode !== 'mr';
        }
        if (env.ceiling) {
            env.ceiling.visible = xrmode !== 'ar' && xrmode !== 'mr';
        }
        current.handle.setZonesVisible(xrmode === 'ar');
        applyPlacement();
    };

    // Hidden objects and locked hotspots follow the state.
    const applyState = () => {
        obstacleversion++;
        current.handle.setHidden(session.getState().hidden);
        current.handle.setLocked((item) => item.kind === 'hotspot' && !!item.zone && session.isZoneLocked(item.zone));
    };

    // Change room (portal or teleport effect), then go to a start point.
    const goTo = (targetscene, spawnid) => {
        if (!targetscene || targetscene === sceneid()) {
            placeAtSpawn(spawnid);
            return Promise.resolve();
        }
        const doc = scenes.find((s) => s.id === targetscene);
        if (!doc || switching) {
            return switching || Promise.resolve();
        }
        const pending = new Pending('vrroomruntime_builtin/viewer:room');
        leaveZones();
        panels.close();
        if (xrpanels) {
            xrpanels.close();
        }
        if (xrinput) {
            xrinput.releaseAll();
        }
        switching = buildScene(THREE, doc, roomOptions()).then((handle) => {
            if (stopped) {
                handle.dispose();
                return undefined;
            }
            if (avatars) {
                // Move the avatars out before the old room releases everything under it.
                avatars.setRoom(handle.root, doc.id);
            }
            current.handle.dispose();
            current = {doc: doc, handle: handle};
            refreshObstaclesWhenLoaded(handle);
            grabbed.clear();
            scene3.add(handle.root);
            session.setScene(doc.id);
            if (avatars) {
                p.live.setLocalMode(xrmode || '3d', doc.id);
            }
            controls.setBounds(handle.environment.bounds);
            applyLook();
            applyState();
            applyRoomKind();
            placeAtSpawn(spawnid);
            if (isPanorama() && (xrmode === 'ar' || xrmode === 'mr') && xr) {
                // A photo is seen from its centre: augmented and mixed reality do not show it.
                xr.exit();
            }
            return getString('scenechanged', 'vrroomruntime_builtin', plainText(doc.name || ''));
        }).then((text) => {
            if (text && !stopped) {
                announce(root, text);
            }
            return undefined;
        }).catch((error) => {
            Log.debug(error);
            if (!stopped) {
                notify(strings.modelfailed, 'warning');
            }
        }).then(() => {
            switching = null;
            pending.resolve();
            return undefined;
        });
        return switching;
    };

    // A start point id anywhere in the activity.
    const goToSpawn = (spawnid) => {
        if (spawnsOf(current.doc).some((s) => s.id === spawnid)) {
            placeAtSpawn(spawnid);
            return;
        }
        const target = scenes.find((s) => spawnsOf(s).some((sp) => sp.id === spawnid));
        if (target) {
            goTo(target.id, spawnid);
        }
    };

    // Activate an interactable: interacted statement, then its panel, room change or media.
    const activate = (item) => {
        if (!item || switching) {
            return;
        }
        let hotspot = item.kind === 'hotspot' ? item : null;
        if (item.opens) {
            const target = findItem(item.opens);
            if (target && target.kind === 'hotspot') {
                hotspot = target;
            }
        }
        const eventid = item.opens ? item.opens : item.id;
        if (hotspot && hotspot.zone && session.isZoneLocked(hotspot.zone)) {
            showLocked();
            return;
        }
        const status = session.record('interacted', 'object', eventid, sceneid());
        if (status === 'locked') {
            showLocked();
            return;
        }
        if (status === 'closed') {
            return;
        }
        if (item.kind === 'portal') {
            const target = item.target && typeof item.target === 'object' ? item.target : {};
            goTo(target.scene, target.spawn);
            return;
        }
        if (item.kind === 'media') {
            toggleMedia(item.id);
        }
        if (hotspot) {
            openHotspot(hotspot);
        }
    };

    // What the walker cannot pass through: the environment (walls, an uploaded room), props and 3D models.
    // Hotspot markers, labels, images and grabbable objects stay walk-through. Rebuilt when the room,
    // its loaded models or the shown/hidden state change.
    let obstaclecache = null;
    const obstacleMeshes = () => {
        const handle = current.handle;
        if (obstaclecache && obstaclecache.handle === handle && obstaclecache.version === obstacleversion) {
            return obstaclecache.list;
        }
        const list = [];
        const add = (object) => {
            if (object) {
                object.traverseVisible((node) => {
                    if (node.isMesh) {
                        list.push(node);
                    }
                });
            }
        };
        // A 360° photo is no wall: there is no walking in it anyway.
        if (handle.environment && !handle.environment.panorama) {
            add(handle.environment.group);
        }
        handle.props.forEach((record) => add(record.mesh));
        handle.items.forEach((record) => {
            if (record.kind === 'model') {
                add(record.group);
            }
        });
        obstaclecache = {handle: handle, version: obstacleversion, list: list};
        return list;
    };
    refreshObstaclesWhenLoaded(current.handle);

    // Controls (desktop and touch) move the rig.
    const controls = attach(camera, canvas, {
        obstacles: obstacleMeshes,
        bounds: current.handle.environment.bounds,
        eyeHeight: EYE,
        rig: rig,
        stick: region(root, 'vrroom-stick'),
        onClick: (ndc) => {
            const item = pick(ndc, Infinity);
            if (item) {
                activate(item);
                return true;
            }
            return false;
        },
        onActivate: () => {
            const item = pick({x: 0, y: 0}, isPanorama() ? PANORAMA_REACH : REACH);
            if (item) {
                activate(item);
            }
        },
        onTouch: () => stage.classList.add('vrroom-touch'),
        onZoom: (factor) => zoomBy(factor),
    });
    // The bar under the room: fullscreen and reversed dragging (the user's preferences).
    const stagebar = createStagebar(root, controls, (p.config && p.config.look) || {});
    // The first place: the saved one when a person still fits there, else a free spot at the start point.
    const placeFirst = (place) => {
        current.handle.root.updateMatrixWorld(true);
        if (isPanorama()) {
            // The centre of the photo, facing the saved direction or the start point's.
            const yaw = place && Number.isFinite(Number(place.yaw)) ? Number(place.yaw) : safeSpawn(null).yaw;
            controls.teleport([0, 0, 0], yaw);
            rememberSpawn(null, place || null);
            return;
        }
        if (place && controls.canStand(vec3(place.position, [0, 0, 0]))) {
            controls.teleport(place.position, place.yaw);
            rememberSpawn(null, place);
            return;
        }
        const spot = safeSpawn(null);
        controls.teleport(spot.position, spot.yaw);
        rememberSpawn(null, null);
        markAtStart(null);
    };
    // After the look and the hidden objects are applied: hidden objects are no obstacles.
    applyLook();
    applyState();
    placeFirst(resume);

    // Where zones are tested from: the walking position, or the head in VR and mixed reality (null: no zones now).
    const zonePoint = () => {
        if (!xrmode) {
            return controls.getPosition();
        }
        if (xrmode === 'vr' || (xrmode === 'mr' && placed)) {
            const head = camera.getWorldPosition(new THREE.Vector3());
            current.handle.root.worldToLocal(head);
            return [head.x, 0, head.z];
        }
        return null;
    };
    const zoneContains = (zone, p) => {
        const c = vec3(zone.center, [0, 0, 0]);
        const s = vec3(zone.size, [0, 0, 0]);
        return Math.abs(p[0] - c[0]) <= s[0] / 2 && Math.abs(p[2] - c[2]) <= s[2] / 2 &&
            p[1] >= c[1] - s[1] / 2 && p[1] <= c[1] + s[1] / 2;
    };

    // Zones, each frame.
    const testZones = () => {
        const p = zonePoint();
        if (!p) {
            return;
        }
        zonesOf(current.doc).forEach((zone) => {
            const isinside = zoneContains(zone, p);
            if (isinside && !inside.has(zone.id)) {
                inside.add(zone.id);
                enterZone(zone);
            } else if (!isinside && inside.has(zone.id)) {
                inside.delete(zone.id);
                if (enteredrecorded.has(zone.id)) {
                    enteredrecorded.delete(zone.id);
                    session.record('exited', 'zone', zone.id, sceneid());
                }
            }
        });
    };

    // A tap on a zone box in AR counts as visiting it (the list view rule).
    const tapZone = (zoneid) => {
        if (session.isZoneLocked(zoneid)) {
            showLocked();
            return;
        }
        if (session.record('interacted', 'zone', zoneid, sceneid()) === 'locked') {
            showLocked();
        }
    };

    // Select with a controller ray, a hand or a screen tap.
    const onXrSelect = (object) => {
        if ((xrmode === 'ar' || xrmode === 'mr') && !placed) {
            placeRoom();
            return true;
        }
        if (!object) {
            return false;
        }
        if (xrpanels && xrpanels.select(object)) {
            return true;
        }
        if (wrist && wrist.isExit(object)) {
            xr.exit();
            return true;
        }
        const found = current.handle.findPickable(object);
        if (!found) {
            return false;
        }
        if (found.kind === 'interactable') {
            activate(findItem(found.id));
        } else if (found.kind === 'zone' && xrmode === 'ar') {
            tapZone(found.id);
        }
        return true;
    };

    const ensureXrInput = () => {
        if (xrinput) {
            return xrinput;
        }
        xrinput = createXrInput(THREE, renderer, rig, {
            camera: camera,
            getTargets: () => {
                const targets = [];
                if (xrpanels && xrpanels.isOpen()) {
                    targets.push(...xrpanels.getTargets());
                }
                if (wrist) {
                    targets.push(...wrist.getTargets());
                }
                return targets.concat(current.handle.pickTargets());
            },
            onSelect: (object) => onXrSelect(object),
            onTeleport: (point) => xrinput.moveHeadTo([point.x, 0, point.z], null),
            // A photo room allows snap turn but no teleport.
            teleportAllowed: () => xrmode === 'vr' && !switching && !isPanorama(),
            snapAllowed: () => xrmode === 'vr' && !switching,
            reach: () => (isPanorama() ? PANORAMA_REACH : XR_REACH),
            bounds: () => current.handle.environment.bounds,
            onGrabStart: (itemid) => {
                const item = findItem(itemid);
                if (!item || item.kind !== 'grabbable') {
                    return false;
                }
                if (grabbed.has(itemid)) {
                    return true;
                }
                const status = session.record('interacted', 'object', itemid, sceneid());
                if (status === 'locked') {
                    showLocked();
                    return false;
                }
                grabbed.add(itemid);
                return status !== 'closed';
            },
            onGrabEnd: () => undefined,
            onConnect: (handedness, grip) => {
                if (handedness === 'left' && wrist && (xrmode === 'vr' || xrmode === 'mr')) {
                    grip.add(wrist.object);
                }
            },
        });
        return xrinput;
    };

    // The wrist panel: required tasks done and time left.
    const updateWrist = () => {
        if (!wrist) {
            return;
        }
        const state = session.getState();
        const timeleft = session.getTimeLeft();
        const requests = [];
        if (state.requiredtotal > 0) {
            requests.push(getString('xrprogress', 'vrroomruntime_builtin', {done: state.requireddone, total: state.requiredtotal}));
        }
        if (timeleft !== null && timeleft !== undefined) {
            requests.push(getString('timeleft', 'vrroomruntime_builtin', clockText(timeleft)));
        }
        Promise.all(requests).then((lines) => {
            if (wrist) {
                wrist.setLines(lines);
            }
            return undefined;
        }).catch((error) => Log.debug(error));
    };

    // Resize (not while an immersive session sizes the canvas).
    const resize = () => {
        if (renderer.xr.isPresenting) {
            return;
        }
        const width = Math.max(1, canvas.clientWidth);
        const height = Math.max(1, canvas.clientHeight);
        renderer.setSize(width, height, false);
        camera.aspect = width / height;
        // A portrait phone keeps a useful width of view, so a board ahead (the story of an escape
        // room) is not cut off at both sides.
        const keepwidth = 2 * Math.atan(Math.tan(MIN_HFOV * DEG / 2) / camera.aspect) / DEG;
        camera.fov = zoomfov !== null ? zoomfov : Math.min(MAX_FOV, Math.max(FOV, keepwidth));
        camera.updateProjectionMatrix();
    };
    // Zoom a photo room by multiplying its field of view (wheel, pinch), within 30° to 90°.
    const zoomBy = (factor) => {
        const f = Number(factor);
        if (!isPanorama() || xrmode || !Number.isFinite(f) || f <= 0) {
            return;
        }
        const base = zoomfov !== null ? zoomfov : camera.fov;
        zoomfov = Math.max(PANORAMA_FOV[0], Math.min(PANORAMA_FOV[1], base * f));
        camera.fov = zoomfov;
        camera.updateProjectionMatrix();
    };
    const observer = new ResizeObserver(resize);
    observer.observe(canvas);
    resize();

    // Immersive sessions.
    xr = createXr(renderer, {
        stage: stage,
        onStart: (mode) => {
            if (stopped) {
                return;
            }
            xrmode = mode;
            placed = mode === 'vr';
            placement = null;
            lasthit = null;
            controls.setEnabled(false);
            panels.close();
            leaveZones();
            session.setChannel(`builtin-${mode}`);
            stage.classList.add('vrroom-xr');
            stage.classList.toggle('vrroom-xr-overlay', mode === 'ar' && xr.domOverlay);
            if (exitbutton) {
                exitbutton.classList.toggle('d-none', !(mode === 'ar' && xr.domOverlay));
            }
            if (mode !== 'vr') {
                // The reference space maps straight onto the world: the room is placed instead.
                rig.position.set(0, 0, 0);
                rig.rotation.set(0, 0, 0);
                rig.updateMatrixWorld(true);
            }
            ensureXrInput();
            if (avatars) {
                avatars.setMode(mode);
            }
            if (mode === 'vr' || mode === 'mr') {
                wrist = createWristPanel(THREE, {exitlabel: strings.exitxr});
                const grip = xrinput.getGrip('left');
                if (grip) {
                    grip.add(wrist.object);
                }
                updateWrist();
            }
            applyLook();
            ensureXrPanels().then(() => {
                if (xrmode && !placed) {
                    notify(strings.xrplace, 'info', true);
                }
                return undefined;
            }).catch((error) => Log.debug(error));
        },
        onEnd: (mode) => {
            if (stopped) {
                return;
            }
            const head = camera.getWorldPosition(new THREE.Vector3());
            const headyaw = userYaw() / DEG;
            xrmode = null;
            placed = false;
            placement = null;
            lasthit = null;
            reticle.visible = false;
            if (xrinput) {
                xrinput.releaseAll();
            }
            if (xrpanels) {
                xrpanels.close();
            }
            if (wrist) {
                wrist.dispose();
                wrist = null;
            }
            leaveZones();
            applyLook();
            stage.classList.remove('vrroom-xr', 'vrroom-xr-overlay');
            if (exitbutton) {
                exitbutton.classList.add('d-none');
            }
            if (xrstatus) {
                xrstatus.textContent = '';
                xrstatus.classList.add('d-none');
            }
            controls.setEnabled(true);
            if (mode === 'vr') {
                controls.teleport([head.x, 0, head.z], headyaw);
            }
            session.setChannel('builtin-3d');
            if (avatars) {
                avatars.setMode('3d');
            }
            resize();
            canvas.focus({preventScroll: true});
        },
    });

    const enterXr = (mode) => {
        if (xr.mode || switching) {
            return;
        }
        const pending = new Pending('vrroomruntime_builtin/viewer:xr');
        // Called straight from the click, so the browser still sees the user's gesture.
        xr.enter(mode).catch((error) => {
            Log.debug(error);
            if (!stopped) {
                showMessage(root, strings.xrfailed, 'warning');
            }
        }).then(() => pending.resolve()).catch(() => pending.resolve());
    };

    // HUD buttons.
    const vrbutton = stage.querySelector('[data-action="vrroom-enter-vr"]');
    const arbutton = stage.querySelector('[data-action="vrroom-enter-ar"]');
    const xrnote = region(root, 'vrroom-xr-note');
    const onHudClick = (e) => {
        const button = e.target.closest('[data-action]');
        if (!button || !stage.contains(button)) {
            return;
        }
        if (button.dataset.action === 'vrroom-enter-vr') {
            e.preventDefault();
            enterXr('vr');
        } else if (button.dataset.action === 'vrroom-enter-ar') {
            e.preventDefault();
            enterXr('ar');
        } else if (button.dataset.action === 'vrroom-exit-xr') {
            e.preventDefault();
            xr.exit();
        }
    };
    stage.addEventListener('click', onHudClick);
    // Taps on the AR overlay's buttons and panels must not also select in the room.
    const onBeforeXrSelect = (e) => {
        if (e.target.closest('button, a, input, select, textarea, label, [data-region="vrroom-overlay"], .vrroom-hud-buttons')) {
            e.preventDefault();
        }
    };
    stage.addEventListener('beforexrselect', onBeforeXrSelect);

    if (!window.isSecureContext && xrnote) {
        xrnote.textContent = strings.xrinsecure;
        xrnote.classList.remove('d-none');
    }
    // What the device offers (from detect()); AR and mixed reality are not offered in a photo room.
    let xrinfo = null;
    const updateXrButtons = () => {
        if (arbutton && xrinfo && xrinfo.ar) {
            arbutton.classList.toggle('d-none', isPanorama());
        }
    };
    detect().then((info) => {
        if (stopped) {
            return undefined;
        }
        xrinfo = info;
        if (vrbutton && info.vr) {
            vrbutton.textContent = strings.entervr;
            vrbutton.classList.remove('d-none');
        }
        if (arbutton && info.ar) {
            arbutton.textContent = info.headset ? strings.entermr : strings.enterar;
            arbutton.classList.remove('d-none');
            updateXrButtons();
        }
        if (info.vr || info.ar) {
            // Ready before the first click, so entering XR keeps the user's gesture.
            ensureXrPanels();
        }
        return undefined;
    }).catch((error) => Log.debug(error));

    // Session messages: state changes, effects and the end of the time.
    const unsubscribe = session.on((message) => {
        if (stopped) {
            return;
        }
        if (message.type === 'timeup') {
            if (xr.mode) {
                xr.exit();
            }
            return;
        }
        if (message.type !== 'change') {
            return;
        }
        applyState();
        panels.refresh();
        updateWrist();
        if (message.unlocked.length) {
            // Whatever was locked may be open now: the "visit the previous station" message goes.
            clearMessage(root, strings.locked);
            if (xrstatus && xrstatus.textContent === strings.locked) {
                xrstatus.textContent = '';
                xrstatus.classList.add('d-none');
            }
        }
        // A zone unlocked while the walker stands in it is entered now. Where the walker stands is
        // read again: this message can arrive in the middle of testZones (entering one zone unlocks
        // the next), when the set of zones the walker is in is not up to date yet, and a teleport
        // must not credit a zone left behind.
        const point = zonePoint();
        message.unlocked.forEach((objective) => {
            if (!point || objective.type !== 'visit_zone' || !objective.zone || !inside.has(objective.zone) ||
                    enteredrecorded.has(objective.zone)) {
                return;
            }
            const zone = zonesOf(current.doc).find((z) => z.id === objective.zone);
            if (zone && zoneContains(zone, point)) {
                enterZone(zone);
            }
        });
        message.effects.forEach((effect) => {
            if (effect.do === 'teleport') {
                goToSpawn(effect.target);
            } else if (effect.do === 'open_question') {
                openQuestion(Number(effect.target));
            } else if (effect.do === 'play_media') {
                const record = mediaOf(effect.target);
                if (record) {
                    playMedia(record);
                }
            }
        });
    });

    // What changes between walkable rooms and 360° photos: walking, tilt, zoom, the phone toggle,
    // the AR button and the controls help read by screen readers.
    const helpwalk = root.querySelector('[data-region="vrroom-controlshelp"]');
    const helppanorama = root.querySelector('[data-region="vrroom-controlshelp-panorama"]');
    const applyRoomKind = () => {
        const panorama = isPanorama();
        controls.setWalk(!panorama);
        controls.setPitchLimit(panorama ? PANORAMA_PITCH : ROOM_PITCH);
        zoomfov = null;
        resize();
        stagebar.setPanorama(panorama);
        updateXrButtons();
        stage.classList.toggle('vrroom-panorama', panorama);
        const help = panorama ? helppanorama : helpwalk;
        if (help && help.id) {
            canvas.setAttribute('aria-describedby', help.id);
        }
    };
    applyRoomKind();

    // Keep the photo sphere around the head, so a photo shows no parallax when the head moves.
    const headpos = new THREE.Vector3();
    const followHead = () => {
        const sphere = panoramaSphere();
        if (!sphere || !sphere.parent) {
            return;
        }
        camera.getWorldPosition(headpos);
        sphere.parent.worldToLocal(headpos);
        sphere.position.copy(headpos);
    };

    // Frame loop. THREE.Timer (not the deprecated THREE.Clock) skips the time a hidden tab was away.
    const timer = new THREE.Timer();
    timer.connect(document);
    renderer.setAnimationLoop((time, frame) => {
        timer.update(time);
        const dt = timer.getDelta();
        if (!xrmode) {
            controls.update(dt);
        } else {
            if ((xrmode === 'ar' || xrmode === 'mr') && !placed) {
                lasthit = xr.getHitPose(frame);
                reticle.visible = !!lasthit;
                if (lasthit) {
                    reticle.matrix.fromArray(lasthit.transform.matrix);
                }
            }
            if (xrinput) {
                xrinput.update(dt);
            }
            if (xrpanels) {
                xrpanels.update(dt);
            }
            wristclock += dt;
            if (wristclock >= WRIST_INTERVAL) {
                wristclock = 0;
                updateWrist();
            }
        }
        followHead();
        testZones();
        spreadIfJoined(dt);
        current.handle.update(dt, timer.getElapsed());
        if (avatars) {
            avatars.update(dt, performance.now());
        }
        renderer.render(scene3, camera);
    });

    session.start('builtin-3d', sceneid());
    // The layout key ties the saved position to the room's surroundings and start point (see prepareRoom).
    const here = () => ({scene: sceneid(), position: controls.getPosition(), yaw: controls.getYaw(), key: layoutKey(current.doc)});
    session.startResume(() => (xrmode ? null : here()));
    clearMessage(root, strings.loading);

    // Behat hooks.
    root.dataset.vrroomReady = '3d';
    root.vrroomTest = {
        enterZone: (name) => {
            const zone = zonesOf(current.doc).find((z) => z.name === name || plainText(z.name) === name);
            if (!zone) {
                return false;
            }
            const c = vec3(zone.center, [0, 0, 0]);
            controls.teleport([c[0], 0, c[2]], null);
            return true;
        },
        clickObject: (name) => {
            const matches = (Array.isArray(current.doc.interactables) ? current.doc.interactables : []).filter((i) => {
                const record = current.handle.items.get(i.id);
                const title = i.content && i.content.title ? plainText(i.content.title) : '';
                return record && record.group.visible && (i.name === name || plainText(i.name) === name || title === name);
            });
            const item = matches.find((i) => i.kind === 'hotspot') || matches[0];
            if (!item) {
                return false;
            }
            activate(item);
            return true;
        },
        currentScene: () => sceneid(),
    };
    canvas.focus({preventScroll: true});

    return {
        /** Stop the 3D view and release everything. */
        stop: () => {
            if (stopped) {
                return;
            }
            if (!xrmode) {
                lastplaces.set(session, here());
            }
            stopped = true;
            p.setStopped();
            if (xr.mode) {
                xr.exit();
            }
            renderer.setAnimationLoop(null);
            timer.dispose();
            observer.disconnect();
            controls.detach();
            stagebar.dispose();
            unsubscribe();
            stage.removeEventListener('click', onHudClick);
            stage.removeEventListener('beforexrselect', onBeforeXrSelect);
            panels.close();
            if (messagetimer) {
                window.clearTimeout(messagetimer);
            }
            if (xrinput) {
                xrinput.dispose();
                xrinput = null;
            }
            if (xrpanels) {
                xrpanels.dispose();
                xrpanels = null;
            }
            if (wrist) {
                wrist.dispose();
                wrist = null;
            }
            session.stop();
            if (avatars) {
                avatars.dispose();
            }
            current.handle.dispose();
            reticle.geometry.dispose();
            reticle.material.dispose();
            renderer.dispose();
            [vrbutton, arbutton, exitbutton, xrnote, xrstatus].forEach((element) => {
                if (element) {
                    element.classList.add('d-none');
                }
            });
            stage.classList.add('d-none');
            stage.classList.remove('vrroom-touch', 'vrroom-xr', 'vrroom-xr-overlay');
            delete root.dataset.vrroomReady;
            delete root.vrroomTest;
        },
    };
};
